export function enrich(topics) {
  return topics.map(topic => {
    let kit = null
    for (const k of API_KIT) {
      if (k.re.test(topic.t) || k.re.test(topic.d)) { kit = k; break }
    }
    return {
      ...topic,
      d: kit ? `${topic.d}\n\n${kit.ref}` : topic.d,
      // rotating canonical examples so consecutive variants differ
      exs: kit?.examples,
    }
  })
}

export default [
  ...DRILLS,
  // ---------------- MutationObserver ----------------
  { t: 'the MutationObserver interface', d: 'MutationObserver watches a DOM node (optionally its whole subtree) for structural or textual changes and delivers them asynchronously: every batch arrives as an array of MutationRecord objects passed to your callback in a microtask, never mid-mutation. Create one with new MutationObserver(callback), then call observe(target, options) choosing what to watch via childList, attributes, and characterData flags. It replaced the deprecated mutation events because batching avoids the layout thrashing those synchronous events caused.', c: "const target = document.querySelector('#list');\nconst mo = new MutationObserver(records => {\n  for (const r of records) {\n    console.log(r.type, r.addedNodes.length, r.removedNodes.length);\n  }\n});\nmo.observe(target, { childList: true, subtree: true });\ntarget.appendChild(document.createElement('li'));" },
  { t: 'MutationObserver observe options', d: 'The options bag controls exactly which mutations you hear about: childList (node additions/removals of target itself), subtree (extend watching to descendants), attributes (attribute changes), attributeFilter (array limiting which attribute names), characterData (text changes on target or text-node descendants), plus attributeOldValue and characterDataOldValue to include previous values in records. Observing nothing relevant throws: childList, attributes, or characterData must be requested. Narrow filters keep callbacks fast on large trees.', c: "mo.observe(editor, {\n  childList: true,\n  subtree: true,\n  characterData: true,\n  characterDataOldValue: true, // record.oldValue filled\n});" },
  { t: 'MutationRecord objects', d: 'Each MutationRecord describes one change: type ("childList", "attributes", or "characterData"), target, addedNodes/removedNodes NodeLists, previousSibling/nextSibling for structural edits, attributeName plus oldValue for attribute writes, and oldValue for text edits when old-value tracking was requested. Records are snapshots, not live views, so reading them later is safe even after the DOM moved on.' },
  { t: 'MutationObserver disconnect and takeRecords', d: 'disconnect() stops the observer permanently until observe() is called again and also discards any queued-but-undelivered records. takeRecords() returns the pending queue synchronously and empties it without invoking the callback, which is handy right before tearing down: drain pending work yourself, then disconnect, ensuring no callback fires afterwards against stale assumptions.', c: "function stopWatching(mo) {\n  const pending = mo.takeRecords(); // handle final batch synchronously\n  if (pending.length) flush(pending);\n  mo.disconnect();\n}" },
  { t: 'attributeFilter performance discipline', d: 'Observing attributes across a large subtree forces the engine to diff every attribute of every descendant; attributeFilter: ["class", "style"] cuts the surface to named attributes only. Combined with omitting subtree when possible and unobserving once a goal is reached, filters turn potentially expensive watchers into negligible overhead.' },
  { t: 'why MutationObserver replaced mutation events', d: 'MutationEvents (DOMSubtreeModified and friends) fired synchronously during every mutation, forcing immediate layout/invalidation work and making batching impossible; they were slow, noisy, and inconsistent. MutationObserver delivers batched records asynchronously with precise old/new details and better cross-browser behavior, which is why mutation events are deprecated everywhere.' },
  { t: 'avoiding MutationObserver feedback loops', d: 'A callback that mutates the very nodes it observes re-triggers itself forever. Standard guards: disconnect before writing and re-observe after (dropping self-caused records), track a boolean "applying" flag checked at callback entry, or compare incoming records against a last-applied snapshot so idempotent writes short-circuit. Chart libraries and virtual-DOM bridges rely on this dance constantly.', c: "let applying = false;\nconst mo = new MutationObserver(() => {\n  if (applying) return;\n  applying = true;\n  normalize(el); // writes into el...\n  applying = false;\n});" },
  { t: 'waiting for framework-rendered nodes', d: 'Frameworks render asynchronously, so code running immediately after a state update may find no elements yet. A small promise helper wrapping MutationObserver resolves on the first matching childList mutation, giving await-ready waitForElement(selector) semantics without polling timers, then disconnects to stay clean.', c: "function waitForSelector(root, selector) {\n  return new Promise(resolve => {\n    const el = root.querySelector(selector);\n    if (el) return resolve(el);\n    const mo = new MutationObserver(() => {\n      const el = root.querySelector(selector);\n      if (el) { mo.disconnect(); resolve(el); }\n    });\n    mo.observe(root, { childList: true, subtree: true });\n  });\n}" },

  // ---------------- IntersectionObserver ----------------
  { t: 'the IntersectionObserver interface', d: 'IntersectionObserver reports when a target element intersects a root (the viewport by default) at configured ratios, replacing scroll-event geometry math. Callbacks fire asynchronously at browser-chosen times, always once initially for every observed target, delivering IntersectionObserverEntry arrays. It powers lazy loading, infinite scroll, sticky headers, and impression analytics without per-scroll-frame cost.', c: "const io = new IntersectionObserver(entries => {\n  for (const en of entries) {\n    console.log(en.target.id, en.isIntersecting, en.intersectionRatio.toFixed(2));\n  }\n});\nio.observe(document.querySelector('#hero'));" },
  { t: 'IntersectionObserver root rootMargin threshold options', d: 'The options object takes root (viewport when null), rootMargin (CSS-like margins shrinking or growing the root box, px or %, e.g. "200px 0px"), and threshold, an array of visibility ratios 0..1 where callbacks trigger on crossings. threshold: 0 fires on any pixel entering/leaving; [0, 0.5, 1] fires at zero, half, and full visibility; a value of 1.0 demands every pixel visible. Callbacks run on crossings between states, not continuously while visible.' },
  { t: 'IntersectionObserverEntry fields', d: 'Each entry exposes target, isIntersecting, intersectionRatio, time (relative to observer creation), boundingClientRect (target box), intersectionRect (visible overlap), rootBounds (root box, null cross-origin), plus isIntersecting companions. Reading boundingClientRect lets you infer travel direction: comparing entry.boundingClientRect.top against previous values tells whether the element is moving up or down, essential for sticky/reveal logic.' },
  { t: 'lazy loading images with IntersectionObserver', d: 'Observe placeholder images carrying data-src, and on the first intersecting entry swap the real URL into src, add a loaded class, and immediately unobserve the image since the job is done. A rootMargin of a few hundred pixels preloads just before the viewport arrives, masking network latency; native loading="lazy" covers simple cases, but the observer remains king when fade-ins or LQIP swaps accompany loads.', c: "const io = new IntersectionObserver((entries, obs) => {\n  for (const en of entries) {\n    if (!en.isIntersecting) continue;\n    const img = en.target;\n    img.src = img.dataset.src;\n    img.classList.add('loaded');\n    obs.unobserve(img);\n  }\n}, { rootMargin: '300px' });\ndocument.querySelectorAll('img[data-src]').forEach(img => io.observe(img));" },
  { t: 'infinite scroll sentinel pattern', d: 'Place an empty sentinel div after the item list and observe it; when it becomes intersecting, fetch the next page, append items, and let the sentinel be pushed below the fold naturally. While fetching, either unobserve or guard with an isLoading flag to prevent duplicate requests, and remember the initial callback fires on observe even before scrolling, seeding page one cleanly.' },
  { t: 'IntersectionObserver asynchronous delivery contract', d: 'Callbacks are NOT synchronized with scroll frames; the browser schedules them after intersections are computed, coalescing changes. Never assume entry data matches the exact current frame for animation-critical math, and do not expect one callback per scrolled pixel, only per threshold crossing. For continuous scroll-linked effects prefer scroll-driven CSS animations or rAF sampling.' },
  { t: 'negative versus positive rootMargin', d: 'Positive rootMargin grows the detection area, triggering before elements visually arrive (preloading). Negative margins shrink it, requiring deeper penetration: rootMargin "-20% 0px" makes a strip of the viewport act as the trigger zone, popular for "section entered middle of screen" reveal effects and analytics where edge grazes should not count.' },

  // ---------------- ResizeObserver ----------------
  { t: 'the ResizeObserver interface', d: 'ResizeObserver notifies you when an element\u2019s content box (or border box, per options) changes size, solving container-responsive components that media queries cannot express because media queries only know the viewport. Callbacks receive ResizeObserverEntry arrays with the new dimensions and fire after layout but before paint, once per observed element initially.', c: "const ro = new ResizeObserver(entries => {\n  for (const en of entries) {\n    canvas.width = en.contentRect.width * devicePixelRatio;\n    canvas.height = en.contentRect.height * devicePixelRatio;\n    draw();\n  }\n});\nro.observe(chartHost);" },
  { t: 'ResizeObserverEntry contentRect and box sizes', d: 'entry.contentRect is a DOMRectReadOnly of the CONTENT box in CSS pixels (padding/border excluded), while entry.borderBoxSize, contentBoxSize, and devicePixelContentBoxSize report more precise block/inline sizes; devicePixelContentBoxSize gives exact physical pixels, eliminating blur in canvas rendering under fractional DPRs. The array-form (newer spec) may hold multiple rows for fragmented boxes, so read index [0].' },
  { t: 'ResizeObserver loop limit errors', d: '"ResizeObserver loop completed with undelivered notifications" appears when a callback resizes something that resizes the observed element again within one frame; the browser defers the extra cycle and eventually surfaces a benign window error event. Guard by comparing new sizes against cached last values and skipping identical writes, or move measurement targets out of the mutated subtree. Treat the error as a signal, not an exception to swallow blindly.' },
  { t: 'ResizeObserver versus window resize event', d: 'window resize fires only for viewport changes; ResizeObserver fires whenever ANY observed box changes, including flex/grid redistribution, sidebar collapse, font loads changing intrinsic sizes, or programmatic style writes. Per-element granularity means components own their responsiveness locally instead of global resize handlers querying every registered widget.' },

  // ---------------- Selection ----------------
  { t: 'the Selection interface', d: 'window.getSelection() returns the document\u2019s current user selection: anchorNode/anchorOffset mark where selection started, focusNode/focusOffset where it ends, so anchor after focus encodes backwards selection. Key operations: toString() for plain text, isCollapsed to detect a bare caret, rangeCount with getRangeAt(0) for rich spans, removeAllRanges(), and extend() to grow programmatically.', c: "document.addEventListener('mouseup', () => {\n  const sel = window.getSelection();\n  if (sel.isCollapsed || !sel.toString().trim()) return;\n  console.log(sel.anchorNode.nodeType, sel.toString().slice(0, 40));\n});" },
  { t: 'selectionchange event tracking', d: 'The document-scoped selectionchange event fires whenever the caret or highlight moves, including focus jumps between editable areas. It fires rapidly, so debounce before measuring ranges for floating toolbars or share-to-quote UIs; read window.getSelection() inside the handler for fresh coordinates rather than caching nodes that may have been replaced.' },
  { t: 'programmatic text selection', d: 'To select content from script: build a Range spanning the desired nodes (range.selectNodeContents(el)), then sel.removeAllRanges(); sel.addRange(range). After focus-stealing operations like button clicks that collapse selections, restoring a stored Range via addRange brings back the highlight, a staple of editor undo and toolbar flows.' },
  { t: 'Selection direction and collapsed states', d: 'direction ("forward", "backward", "none") tells how anchor relates to focus; type is "Range" for real selections or "Caret"/"None" otherwise. Backwards selections matter for tools that trim trailing whitespace differently per side, and type==="None" occurs in some browsers when selection lives inside non-editable shadow roots, worth guarding before calling getRangeAt(0).' },

  // ---------------- Range ----------------
  { t: 'the Range interface boundaries', d: 'document.createRange() models a contiguous fragment between two boundary points: startContainer/startOffset and endContainer/endOffset, where offsets count characters in Text nodes but child indexes in Elements. Ranges are live views over the DOM, adjust themselves as surrounding content changes, and collapse automatically if content vanishes. Everything from text selection to editor anchors builds on these four numbers.', c: "const range = document.createRange();\nrange.setStart(p.firstChild, 4);\nrange.setEnd(p.firstChild, 12);\nconsole.log(range.toString()); // chars 4..11\nconsole.log(range.collapsed);" },
  { t: 'selectNode versus selectNodeContents', d: 'range.selectNode(el) spans the element INCLUDING its tags (boundaries sit in the parent), while selectNodeContents(el) spans only its children, starting inside the element. Choosing wrong shifts insertion/extraction by one boundary level, a classic off-by-one-container bug when wrapping or deleting nodes programmatically.' },
  { t: 'extractContents cloneContents deleteContents', d: 'extractContents() removes the fragment and hands it back for reinsertion (move semantics used by drag-out-of-editor); cloneContents() copies without touching the tree; deleteContents() removes outright. Returned fragments preserve hierarchy, so extracted rich content can be appended into another container with structure intact. surroundContents(parent) wraps the range but throws across partially-selected element boundaries, so extract-then-append is the robust general path.' },
  { t: 'Range insertNode positioning', d: 'range.insertNode(node) inserts at the START boundary, splitting text nodes as needed; the range then contains the inserted node. Insert before extracting patterns rely on collapsing the range first (range.collapse(false) moves both points to the end) so successive inserts append in order instead of nesting backwards.' },
  { t: 'positioning UI with Range getBoundingClientRect', d: 'A Range\u2019s getBoundingClientRect() returns the union box of its visible content, the precise way to place tooltips, mention menus, or formatting toolbars exactly over selected TEXT rather than whole elements. Combine with selectionchange debouncing: measure sel.getRangeAt(0).getBoundingClientRect(), convert viewport coords with window.scrollX/Y, position an absolutely-placed layer.', c: "const rect = sel.getRangeAt(0).getBoundingClientRect();\ntoolbar.style.left = rect.left + rect.width / 2 + window.scrollX + 'px';\ntoolbar.style.top = (rect.top - 48) + window.scrollY + 'px';" },

  // ---------------- FormData ----------------
  { t: 'the FormData interface', d: 'FormData models a set of name/value entries destined for multipart/form-data submission. new FormData(formElement) harvests every enabled control that has a name (inputs, selects, textareas, file pickers), while empty instances accept programmatic append/set for building bodies from arbitrary JS data. Passing it as a fetch body sets the multipart boundary header automatically, making it the standard file-upload vehicle.', c: "form.addEventListener('submit', async e => {\n  e.preventDefault();\n  const fd = new FormData(form);\n  fd.append('client', 'web-v2');\n  const res = await fetch('/api/upload', { method: 'POST', body: fd });\n  console.log((await res.json()).ok);\n});" },
  { t: 'FormData append versus set', d: 'append(name, value) ADDS another entry, permitting repeated names that server frameworks see as arrays; set(name, value) REPLACES every existing entry with that name, guaranteeing single-valued semantics. Choosing wrongly flips checkbox-group and multi-tag payloads silently. delete(name) clears all matching entries, and has(name) checks existence regardless of count.' },
  { t: 'inspecting FormData entries', d: 'FormData iterates [name, value] pairs (for (const [k, v] of fd)), and offers get(name) returning the FIRST match or null, getAll(name) returning every match as an array, plus keys()/values()/entries() iterators. Files appear as File objects in values. Object.fromEntries(fd) collapses duplicates to their LAST value, so only use it when names are guaranteed unique.', c: "const fd = new FormData();\nfd.append('tag', 'a');\nfd.append('tag', 'b');\nconsole.log(fd.get('tag'));            // \"a\"\nconsole.log(fd.getAll('tag'));         // [\"a\", \"b\"]\nconsole.log(Object.fromEntries(fd).tag); // \"b\" (last wins)" },
  { t: 'FormData file entries and filenames', d: 'append(name, blob, filename) attaches a Blob or File, optionally renaming it independently of blob.name; input[type=file] entries land as File objects harvested automatically. Server-side validation still matters: client MIME types are advisory, and appending files does not encode contents beyond standard multipart framing.' },
  { t: 'never hand-set multipart Content-Type', d: 'When body is a FormData instance, fetch generates Content-Type: multipart/form-data; boundary=... internally. Overriding that header breaks the boundary and servers reject the request. The same applies to URLSearchParams (application/x-www-form-urlencoded) and Blob bodies: let the platform derive content types unless a backend genuinely requires exotic framing.' },

  // ---------------- CustomEvent ----------------
  { t: 'the CustomEvent interface', d: 'CustomEvent extends Event with a detail property carrying arbitrary data, created via new CustomEvent(type, { detail, bubbles, cancelable, composed }). Dispatch it on any EventTarget with dispatchEvent, and listeners read event.detail. It is the built-in pub/sub primitive for decoupling modules, web-component APIs, and third-party hooks without importing a messaging library.', c: "const bus = new EventTarget();\nbus.addEventListener('cart:add', e => {\n  console.log('added', e.detail.sku, 'qty', e.detail.qty);\n});\nbus.dispatchEvent(new CustomEvent('cart:add', {\n  detail: { sku: 'TS-01', qty: 2 },\n}));" },
  { t: 'dispatchEvent synchronous delivery', d: 'dispatchEvent invokes listeners SYNCHRONOUSLY on the calling thread: all handlers finish before the next line executes, and exceptions propagate to the dispatcher (unlike listener-caused async flows). Ordering follows registration order for the same phase/type. This determinism makes CustomEvent chains predictable but means slow handlers stall the dispatcher, so heavy work belongs behind queueMicrotask or rAF.' },
  { t: 'cancelable events and preventDefault return', d: 'With cancelable: true, a handler calling event.preventDefault() makes dispatchEvent return false and sets event.defaultPrevented, letting emitters learn consumers vetoed the action. Without cancelable the flag is inert and dispatchEvent always returns true. This is the platform\u2019s built-in veto channel, used by dialog cancel, beforeunload-style flows, and editor beforeinput.', c: "bus.addEventListener('save', e => e.preventDefault());\nconst ev = new CustomEvent('save', { cancelable: true });\nconst allowed = bus.dispatchEvent(ev);\nconsole.log(allowed, ev.defaultPrevented); // false true" },
  { t: 'bubbles composed propagation flags', d: 'bubbles: true lets the event climb from dispatch target through ancestors so delegated listeners higher up can catch it; composed: true additionally lets it cross shadow-DOM boundaries, retargeted to the host. Plain dispatches default to neither, stranding events on isolated targets, the usual reason "my listener on document never fires".' },

  // ---------------- ShadowRoot ----------------
  { t: 'attachShadow and ShadowRoot basics', d: 'element.attachShadow({ mode: "open" }) creates and returns a ShadowRoot, an encapsulated tree rendered inside the host element; mode "closed" hides shadowRoot references from outside code. Styles defined inside the shadow tree are scoped to it, light-DOM children project through <slot> elements, and the pair (host + shadowRoot) is the foundation of web components.', c: "class MyCard extends HTMLElement {\n  connectedCallback() {\n    const root = this.attachShadow({ mode: 'open' });\n    root.innerHTML = `\n      <style>h2 { color: rebeccapurple; }</style>\n      <h2><slot name=\"title\">fallback</slot></h2>\n      <p><slot></slot></p>`;\n  }\n}\ncustomElements.define('my-card', MyCard);" },
  { t: 'slot distribution and slotchange', d: '<slot> marks where light-DOM children render inside a shadow tree; named slots route children bearing slot="name", the unnamed slot catches the rest, and slot fallback content shows when nothing is projected. Slots emit slotchange when distributed nodes change, and slot.assignedNodes({ flatten: true }) reveals what actually landed, enabling empty-state UIs and per-child decoration.' },
  { t: 'styling across the shadow boundary', d: 'Document styles cannot reach inside a shadow root except through inherited properties (color, font) and CSS custom properties, which intentionally pierce boundaries as the sanctioned theming channel. Inside out: :host styles the host element, :host(.class) conditions on it, ::slotted(el) targets projected light-DOM children only at top level. Design systems expose theme hooks as --custom-props precisely because selectors cannot penetrate.' },
  { t: 'event retargeting in shadow DOM', d: 'Events originating inside a shadow tree appear, from outside listeners, to target the HOST element; the true chain is available via event.composedPath(). Events with composed: false (like focus legacy behavior) stop at the boundary entirely. Retargeting preserves encapsulation while keeping delegation working, and composedPath()[0] is how overlay libraries find the real clicked node.' },
  { t: 'closed shadow roots and encapsulation limits', d: 'mode "closed" makes element.shadowRoot return null, blocking outside inspection, but it is privacy theater rather than security: composedPath leaks internals, and you hold references anyway inside the component. Closed mode mainly signals API intent and prevents accidental tampering; genuine isolation comes from the scoping itself, not the mode flag.' },

  // ---------------- CustomElementRegistry ----------------
  { t: 'customElements define and naming rules', d: 'customElements.define(name, constructor) registers a custom element; the name MUST contain a hyphen (kebab-case, e.g. <my-counter>) to reserve it apart from future platform tags, and defining the same name twice throws. Autonomous elements extend HTMLElement; customized built-ins specify { extends: "button" } and ride existing semantics via the is attribute, though Safari historically declined built-in support.' },
  { t: 'custom element lifecycle callbacks', d: 'The element class implements lifecycle hooks: constructor (runs at upgrade; may attachShadow and wire private state but must NOT read attributes or children), connectedCallback (inserted into a document; ideal for subscriptions/rendering), disconnectedCallback (cleanup), adoptedCallback (moved between documents), and attributeChangedCallback(name, oldVal, newVal), which fires ONLY for names listed in the static observedAttributes array.', c: "static get observedAttributes() { return ['count', 'disabled']; }\nattributeChangedCallback(name, oldV, newV) {\n  if (oldV === newV) return;\n  if (name === 'count') this.#render();\n  this.toggleAttribute('aria-disabled', this.hasAttribute('disabled'));\n}" },
  { t: 'element upgrades and whenDefined', d: 'Markup parsed BEFORE define() creates elements that sit unupgraded until registration upgrades them retroactively, firing constructor and connectedCallback then. customElements.get(name) returns the class or undefined, customElements.upgrade(node) force-upgrades subtrees, and customElements.whenDefined(name) returns a promise, letting code await availability before interacting, crucial when scripts load in uncertain order.' },
  { t: 'constructor constraints in custom elements', d: 'During the constructor you may create the shadow root, bind event handlers, and initialize private fields, but must not inspect attributes (not yet applied), touch childNodes (empty), or throw, or the element renders as broken inline. Defer DOM reads/writes to connectedCallback and react to attributeChangedCallback for configuration, the discipline preventing most upgrade-order crashes.' },

  // ---------------- Storage ----------------
  { t: 'the Storage interface methods', d: 'localStorage and sessionStorage implement getItem(key) (null when absent), setItem(key, value), removeItem(key), clear(), key(index), and a length property, storing UTF-16 strings per origin. Values persist across tabs and restarts for localStorage; sessionStorage scopes to one tab\u2019s session history. Access is synchronous and main-thread-bound, so bulky payloads jank rendering, keep entries small.', c: "localStorage.setItem('theme', 'dark');\nconsole.log(localStorage.getItem('theme')); // \"dark\"\nconsole.log(localStorage.getItem('nope'));  // null\nfor (let i = 0; i < localStorage.length; i++) {\n  console.log(localStorage.key(i));\n}\nlocalStorage.removeItem('theme');" },
  { t: 'strings-only serialization pitfalls', d: 'Storage coerces everything to strings: setItem("flag", false) stores "false", and objects stringify to "[object Object]" unless you JSON.stringify explicitly, paired with a guarded JSON.parse (try/catch, since corrupted or legacy entries throw). Numbers round-trip as strings, so parse on read and design keys around stringly-typed truthiness traps like "false" being truthy as a non-empty string.' },
  { t: 'quota exceeded error handling', d: 'Origins get roughly 5MB per storage area; exceeding it on setItem throws QuotaExceededError (or silently fails in odd privacy configurations), so production code wraps writes in try/catch and degrades gracefully, pruning old keys via clear or LRU eviction. Private-browsing modes historically threw even on tiny writes, another reason defensive writes beat assuming success.' },
  { t: 'storage event cross-tab synchronization', d: 'Mutating localStorage fires a storage event in EVERY OTHER same-origin tab (never the writer), delivering key, oldValue, newValue, url, and storageArea. It enables logout-everywhere, live theme switching, and cart syncing without polling; parse defensively since newValue arrives as a string and may be null for removals.', c: "window.addEventListener('storage', e => {\n  if (e.key !== 'theme') return;\n  applyTheme(e.newValue ?? 'light'); // null = removed\n});" },
  { t: 'what never belongs in localStorage', d: 'Any JavaScript-reachable token (JWTs, API keys) in localStorage is readable by every injected script, turning one XSS into full account takeover; cookies flagged HttpOnly exist precisely for that reason. Also avoid unbounded caches, PII regulated by policy, and anything needing integrity guarantees, storage has none. Prefer memory + HttpOnly cookies for secrets, IndexedDB for large structured data.' },
  { t: 'TTL wrapper pattern for storage', d: 'Wrap setItem payloads as { v, exp } timestamps, treating expired reads as misses, to give localStorage cache semantics it lacks natively; combine with version fields so schema changes invalidate old entries wholesale instead of crashing parsers. This tiny layer converts raw persistence into a safe cache for API responses and feature flags.', c: "function save(key, value, ttlMs) {\n  localStorage.setItem(key, JSON.stringify({ v: value, exp: Date.now() + ttlMs }));\n}\nfunction load(key) {\n  try {\n    const rec = JSON.parse(localStorage.getItem(key));\n    if (!rec || Date.now() > rec.exp) { localStorage.removeItem(key); return null; }\n    return rec.v;\n  } catch { return null; }\n}" },

  // ---------------- URL ----------------
  { t: 'the URL interface', d: 'new URL(url, base?) parses and validates an absolute URL (or relative resolved against base, throwing TypeError on failure), exposing protocol, username/password, host, hostname, port, pathname, search, hash, origin, and href as mutable properties whose writes re-serialize the whole href normalized. It eliminates regex URL surgery and pairs with history.replaceState for clean address-bar state.', c: "const u = new URL('https://shop.example.com:443/catalog/shoes?size=42&tag=sale#top');\nconsole.log(u.origin);     // \"https://shop.example.com\"\nconsole.log(u.pathname);   // \"/catalog/shoes\"\nconsole.log(u.hash);       // \"#top\"\nu.searchParams.set('page', '2');\nconsole.log(u.href);" },
  { t: 'URL relative resolution and errors', d: 'new URL("/api/v2", "https://api.example.com/v1") resolves relatives exactly like a browser would (protocol-relative, ../, ./ all honored), while missing base for a relative string throws TypeError, so constructors double as strict validators. Catch and fall back rather than letting malformed user links crash form handlers or redirect builders.' },
  { t: 'URL normalization on write', d: 'Assigning any component re-serializes href with canonicalization: default ports drop (443 from https), spaces percent-encode, pathname gains leading slashes. Round-tripping user input through new URL(input).href sanitizes sloppy links predictably, though it does NOT verify safety, javascript: URLs parse happily, so scheme-allowlist separately before navigation.' },
  { t: 'syncing URL.searchParams with url.search', d: 'url.searchParams is a live URLSearchParams view over the serialized query: mutations reflect in url.search and href immediately. Conversely editing url.search re-parses searchParams. Building URLs by setting searchParams beats string concatenation, which breaks on &, =, and unicode, the classic handcrafted-query bug family.' },

  // ---------------- URLSearchParams ----------------
  { t: 'the URLSearchParams interface', d: 'URLSearchParams parses and edits application/x-www-form-urlencoded queries: construct from a string ("a=1&b=2"), an object ({ page: 2 }), an iterable of pairs, or another instance. Methods get/getAll/has/append/set/delete plus iterators cover every need, and toString() re-encodes correctly, making it the only sane way to build querystrings dynamically.', c: "const sp = new URLSearchParams({ page: '2', tag: 'sale' });\nsp.append('tag', 'new');\nconsole.log(sp.get('page'));          // \"2\"\nconsole.log(sp.getAll('tag'));        // [\"sale\", \"new\"]\nconsole.log(sp.toString());           // page=2&tag=sale&tag=new" },
  { t: 'URLSearchParams get versus getAll', d: 'get(name) returns the FIRST value for a key or null when absent; getAll(name) returns every value in order as an array (empty when missing). Repeated keys arise from multi-select checkboxes, comma-free tag inputs, and arrays-by-repetition conventions, so APIs consuming such params must use getAll or they silently truncate to the first entry.' },
  { t: 'URLSearchParams encoding rules', d: 'Encoding follows application/x-www-form-urlencoded: spaces become "+", reserved characters percent-encode (&, =, #), unicode encodes as UTF-8 sequences, and decoding reverses it, with "+" decoded back to space. Manual concatenation produces exactly the bugs this prevents, ampersands inside values splitting parameters invisibly.' },
  { t: 'sorting query params for stable identity', d: 'sort() orders entries alphabetically by name, canonicalizing URLs whose param order varies (analytics dedupe, cache-key normalization, signature computation). Call it before toString()/href comparison to decide whether two URLs are semantically equal regardless of insertion order.', c: "const sp = new URLSearchParams('z=1&a=2&m=3');\nsp.sort();\nconsole.log(sp.toString()); // a=2&m=3&z=1" },
  { t: 'iterating URLSearchParams entries', d: 'URLSearchParams is iterable: for (const [key, value] of sp) visits every entry INCLUDING repeats, and [...sp] materializes pairs for Array methods. Spread into Map collapses duplicates to last-wins, mirroring Object.fromEntries, so preserve multiplicity deliberately rather than accidentally.' },
]

// Worker-safe output-tracing snippets (deterministic console output):
// c = code, o = expected output, e = explanation
export const snippets = [
  {
    c: "const sp = new URLSearchParams('k=first&k=second');\nconsole.log(sp.get('k'));\nconsole.log(sp.getAll('k').length);\nconsole.log(sp.has('missing'));",
    o: '"first"\n2\nfalse',
    e: 'get("k") returns only the FIRST value for a repeated key; getAll returns every value in order, so its array holds two entries; has("missing") is false since the key was never appended.',
  },
  {
    c: "const fd = new FormData();\nfd.append('tag', 'a');\nfd.append('tag', 'b');\nfd.set('tag', 'c');\nconsole.log(fd.getAll('tag').length);\nfd.append('qty', '1');\nconsole.log([...fd.keys()].join(','));\nconsole.log(fd.has('qty'));",
    o: '1\n"tag,qty"\ntrue',
    e: 'set("tag","c") REPLACES both earlier appends, leaving one entry; subsequent append adds qty, so keys serialize in insertion order as tag,qty; has confirms presence.',
  },
  {
    c: "const sp = new URLSearchParams('z=26&m=13&a=1');\nsp.sort();\nconsole.log(sp.toString());",
    o: '"a=1&m=13&z=26"',
    e: 'sort() reorders entries alphabetically by name, producing a canonical query string independent of original order, useful for cache keys and signatures.',
  },
  {
    c: "const u = new URL('https://api.example.com:443/v1/items?page=2#stats');\nconsole.log(u.origin);\nconsole.log(u.pathname);\nconsole.log(u.searchParams.get('page'));\nconsole.log(u.port);",
    o: '"https://api.example.com"\n"/v1/items"\n"2"\n""',
    e: 'https defaults to port 443, so the URL normalizes port to an empty string; origin excludes any path; searchParams.get decodes the query value; pathname stays untouched.',
  },
  {
    c: "const u = new URL('/v2/orders', 'https://api.example.com/v1/customers');\nconsole.log(u.href);\nu.searchParams.set('limit', '5');\nconsole.log(u.search);",
    o: '"https://api.example.com/v2/orders"\n"?limit=5"',
    e: 'An absolute-path relative ("/v2/orders") replaces the entire path of the base, keeping only scheme/host; set then seeds the query, serialized with its "?" prefix in search.',
  },
  {
    c: "console.log(new URLSearchParams({ q: 'a b&c' }).toString());",
    o: '"q=a+b%26c"',
    e: 'Spaces encode as "+" and the ampersand percent-encodes as %26 under application/x-www-form-urlencoded rules, so the value survives round-trips instead of splitting into fake parameters.',
  },
  {
    c: "const bus = new EventTarget();\nbus.addEventListener('tick', () => console.log('one'));\nbus.addEventListener('tick', () => console.log('two'));\nbus.dispatchEvent(new CustomEvent('tick'));\nconsole.log('three');",
    o: '"one"\n"two"\n"three"',
    e: 'dispatchEvent runs listeners synchronously in registration order; the final console.log waits until both handlers finish, demonstrating deterministic CustomEvent delivery.',
  },
  {
    c: "const bus = new EventTarget();\nbus.addEventListener('save', e => e.preventDefault());\nconst ev = new CustomEvent('save', { cancelable: true, detail: { id: 7 } });\nconst allowed = bus.dispatchEvent(ev);\nconsole.log(allowed, ev.defaultPrevented, ev.detail.id);",
    o: 'false true 7',
    e: 'A cancelable event vetoed via preventDefault makes dispatchEvent return false and sets defaultPrevented; detail passes payload untouched, here the id 7.',
  },
  {
    c: "const ev = new CustomEvent('plain');\nconsole.log(ev.bubbles, ev.cancelable, ev.detail);",
    o: 'false false undefined',
    e: 'Without an init dict, bubbles and cancelable default to false and detail is undefined, which is why listeners on ancestors never fire and payload reads yield undefined.',
  },
  {
    c: "const sp = new URLSearchParams('a=1');\nsp.append('a', '2');\nsp.delete('a');\nconsole.log(sp.has('a'));\nconsole.log(JSON.stringify(sp.toString()));",
    o: 'false\n""',
    e: 'delete removes ALL entries for the key, so has flips to false and the query serializes to an empty string, ready for fresh params without leftovers.',
  },
]
